    },
    {
        "zhuang": "Dawz diuz buh de daeuj daenj lo.",
        "zh": "拿那件衣服来穿了。",
        "source": "textbook"
    },
    {
        "zhuang": "Ok ndit lo.",
        "zh": "出太阳了",
