    },
    {
        "zhuang": "Hwnj dangz le.",
        "zh": "上课了",
        "source": "textbook"
    },
    {
        "zhuang": "Ok rumz lo.",
        "zh": "刮风了。",
        "source": "textbook"
    },
    {
        "zhuang": "Doek fwn lo.",
        "zh": "下雨了",
        "source": "textbook"
    },
    {
        "zhuang": "Ndwn dwk!",
        "zh": "站着",
        "source": "textbook"
    },
    {
        "zhuang": "Re!",
        "zh": "注意！",
        "source": "textbook"
    },
    {
        "zhuang": "Dai lo, yuep bae!",
        "zh": "天哪，真是惊心动魄！",
        "source": "textbook"
    },
    {
        "zhuang": "Heuh de daeuj laeng gou guhcaemz.",
        "zh": "请他来我家玩。",
        "source": "textbook"
    },
    {
        "zhuang": "Aeu aendaeh daeuj hawj gou.",
        "zh": "把袋子拿来给我。",
        "source": "textbook"
    },
    {
        "zhuang": "Raemj faexdan ma san aen'gyoi.",
        "zh": "砍竹子来编个泥箕。",
        "source": "textbook"
    },
    {
        "zhuang": "Itdingh guh hong liux bae!",
        "zh": "一定要完成任务！",
        "source": "textbook"
    },
    {
        "zhuang": "Yaek roengzrengz doegsaw!",
        "zh": "要努力学习！",
        "source": "textbook"
    },
    {
        "zhuang": "Ak raixcaix!",
        "zh": "很有水平！",
        "source": "textbook"
    },
    {
        "zhuang": "Gvai lai lo.",
        "zh": "太聪明了。",
